-- ============================================================
-- 063: X04 SQL exercises re-keyed to the September 2026 Seduh dataset.
--
--   Supersedes 055 (and the X04 description rewrites in 059, which are folded
--   back into the generator). The playground now serves the RAW tables rather
--   than the cleaned ones — more rows, duplicate order_id values, mixed
--   channel spellings — so every expected value from 055 was stale.
--
--   The X01-X12 program builds one portfolio project on the Seduh data, so the
--   SQL session now practises on that data instead of the synthetic ecommerce
--   schema. Every exercise is one of the brief's own business questions, and
--   the learner's playground totals match the workbook on their disk.
--
--   dataset_name moves to 'seduh', which is what routes the browser to the
--   right database. The 04/05/06/F08 sessions keep 'ecommerce' and are
--   untouched.
--
--   Generated by scripts/gen-x04-exercises.py — every expected value below was
--   produced by executing the solution against the real dataset. Do not edit by
--   hand; re-run the script instead.
--
--   UPDATE in place, matched on order_num, rather than DELETE + INSERT like 055
--   did: exercise_submissions.exercise_id cascades on delete, so re-inserting
--   would take every learner's submitted attempt with it. The row's identity is
--   what has to survive; only its content changes.
--
--   An INSERT is still emitted, guarded by NOT EXISTS, so a database that never
--   ran 055 ends up with the same eight exercises.
-- ============================================================

-- #1 — Roasted Beans, Most Expensive First
UPDATE public.exercises e
SET type = 'sql',
    title_en = 'Roasted Beans, Most Expensive First',
    title_id = 'Roasted Beans, Termahal Dulu',
    description_en = 'Seduh sells six categories. List every product in the **Roasted Beans** category, most expensive first. Return exactly: `product_name`, `base_price`. This is the raw data, so `category` is not spelled consistently yet — match the exact value and note which rows that leaves out.',
    description_id = 'Seduh menjual enam kategori. Tampilkan semua produk kategori **Roasted Beans**, termahal dulu. Kembalikan tepat: `product_name`, `base_price`. Ini data mentah, jadi penulisan `category` belum seragam — cocokkan nilai persisnya dan perhatikan baris mana yang jadi tidak ikut.',
    starter_code = '-- Roasted Beans products, most expensive first
-- Return: product_name, base_price
',
    solution_code = 'SELECT product_name, base_price FROM products WHERE category = ''Roasted Beans'' ORDER BY base_price DESC;',
    test_cases = '[{"id": "tc1", "validation_type": "exact_match", "expected_rows": [{"product_name": "House Blend 1kg", "base_price": 349000}, {"product_name": "House Blend 500g", "base_price": 195000}, {"product_name": "Cold Brew Blend 500g", "base_price": 178000}, {"product_name": "Single Origin Sampler 4x100g", "base_price": 165000}, {"product_name": "Manuk Gading Natural 200g", "base_price": 145000}, {"product_name": "Decaf Blend 200g", "base_price": 135000}, {"product_name": "Arabika Toraja Sapan 200g", "base_price": 125000}, {"product_name": "Arabika Flores Bajawa 200g", "base_price": 122000}, {"product_name": "Arabika Kintamani Bali 200g", "base_price": 118000}, {"product_name": "Arabika Java Preanger 200g", "base_price": 110000}, {"product_name": "Espresso Blend 250g", "base_price": 99000}, {"product_name": "House Blend 200g", "base_price": 89000}, {"product_name": "Robusta Lampung 250g", "base_price": 78000}], "description_en": "Returns the correct 13 row(s) with the right values", "description_id": "Mengembalikan 13 baris yang benar dengan nilai yang tepat", "points": 70}, {"id": "tc2", "validation_type": "contains_columns", "expected_columns": ["product_name", "base_price"], "description_en": "Returns the required columns: product_name, base_price", "description_id": "Mengembalikan kolom yang diminta: product_name, base_price", "points": 30}]'::jsonb,
    hints_en = '["Filter with WHERE category = ...", "ORDER BY ... DESC puts the largest first"]'::jsonb,
    hints_id = '["Filter dengan WHERE category = ...", "ORDER BY ... DESC menaruh yang terbesar dulu"]'::jsonb,
    difficulty = 'easy',
    dataset_name = 'seduh'
