-- #2 — Which Channels Does Seduh Sell On?
UPDATE public.exercises e
SET type = 'sql',
    title_en = 'Which Channels Does Seduh Sell On?',
    title_id = 'Seduh Berjualan di Channel Apa Saja?',
    description_en = 'Count the **completed** orders per sales channel. Remember: only `order_status = ''Completed''` counts. Return exactly: `channel`, `orders`, busiest first. The data is raw, so you will get far more than four channels — that mess is the finding.',
    description_id = 'Hitung jumlah order **Completed** per channel penjualan. Ingat: hanya `order_status = ''Completed''` yang dihitung. Kembalikan tepat: `channel`, `orders`, terbanyak dulu. Datanya mentah, jadi channel-nya akan jauh lebih dari empat — keberantakan itulah temuannya.',
    starter_code = '-- Completed orders per channel
-- Return: channel, orders
',
    solution_code = 'SELECT channel, COUNT(*) AS orders FROM orders WHERE order_status = ''Completed'' GROUP BY channel ORDER BY orders DESC;',
    test_cases = '[{"id": "tc1", "validation_type": "exact_match", "expected_rows": [{"channel": "Tokopedia", "orders": 6857}, {"channel": "Shopee", "orders": 6520}, {"channel": "Webstore", "orders": 5073}, {"channel": "TikTok Shop", "orders": 4838}, {"channel": "Webstore ", "orders": 52}, {"channel": "tokopedia", "orders": 50}, {"channel": " Webstore", "orders": 50}, {"channel": "WEBSTORE", "orders": 45}, {"channel": "Shoppee", "orders": 44}, {"channel": " Shopee", "orders": 44}, {"channel": "Tiktok shop ", "orders": 39}, {"channel": "TIKTOK SHOP", "orders": 37}, {"channel": "TOKOPEDIA", "orders": 36}, {"channel": "Tokopedia ", "orders": 34}, {"channel": "Tokopdia", "orders": 34}, {"channel": "Shopee ", "orders": 34}, {"channel": "Tiktok Shop", "orders": 33}, {"channel": "TikTok shop", "orders": 33}, {"channel": "webstore", "orders": 32}, {"channel": "tiktok shop", "orders": 32}, {"channel": "shopee", "orders": 28}, {"channel": "SHOPEE", "orders": 27}, {"channel": " Tokopedia", "orders": 27}], "description_en": "Returns the correct 23 row(s) with the right values", "description_id": "Mengembalikan 23 baris yang benar dengan nilai yang tepat", "points": 70}, {"id": "tc2", "validation_type": "contains_columns", "expected_columns": ["channel", "orders"], "description_en": "Returns the required columns: channel, orders", "description_id": "Mengembalikan kolom yang diminta: channel, orders", "points": 30}]'::jsonb,
    hints_en = '["WHERE filters rows before grouping", "COUNT(*) counts rows in each group"]'::jsonb,
    hints_id = '["WHERE memfilter baris sebelum pengelompokan", "COUNT(*) menghitung baris di tiap grup"]'::jsonb,
    difficulty = 'easy',
    dataset_name = 'seduh'
