-- #3 — Q2 — Which Channel Is Most Valuable After Discount?
UPDATE public.exercises e
SET type = 'sql',
    title_en = 'Q2 — Which Channel Is Most Valuable After Discount?',
    title_id = 'Q2 — Channel Mana yang Paling Bernilai Setelah Diskon?',
    description_en = 'Gross revenue flatters a discount-heavy channel. Compute revenue **after** discount: `quantity * unit_price * (1 - discount_pct)`, completed orders only. Return exactly: `channel`, `revenue` (rounded, no decimals), highest first. Raw channel spellings split one channel across several rows; say so in your answer.',
    description_id = 'Revenue kotor membuat channel yang banyak diskon terlihat bagus. Hitung revenue **setelah** diskon: `quantity * unit_price * (1 - discount_pct)`, hanya order Completed. Kembalikan tepat: `channel`, `revenue` (dibulatkan, tanpa desimal), tertinggi dulu. Penulisan channel yang mentah memecah satu channel jadi beberapa baris; sebutkan itu di jawabanmu.',
    starter_code = '-- Q2: revenue after discount, per channel
-- Return: channel, revenue
',
    solution_code = 'SELECT channel, ROUND(SUM(quantity * unit_price * (1 - discount_pct))) AS revenue FROM orders WHERE order_status = ''Completed'' GROUP BY channel ORDER BY revenue DESC;',
    test_cases = '[{"id": "tc1", "validation_type": "exact_match", "expected_rows": [{"channel": "Tokopedia", "revenue": 1927430950.0}, {"channel": "Shopee", "revenue": 1844757800.0}, {"channel": "Webstore", "revenue": 1429215550.0}, {"channel": "TikTok Shop", "revenue": 1378095650.0}, {"channel": "Webstore ", "revenue": 14944100.0}, {"channel": " Webstore", "revenue": 14804050.0}, {"channel": "Shoppee", "revenue": 14233650.0}, {"channel": " Shopee", "revenue": 13199750.0}, {"channel": "tokopedia", "revenue": 12777950.0}, {"channel": "TikTok shop", "revenue": 12774900.0}, {"channel": "TOKOPEDIA", "revenue": 11485450.0}, {"channel": "Tiktok shop ", "revenue": 11083500.0}, {"channel": "WEBSTORE", "revenue": 10929850.0}, {"channel": "TIKTOK SHOP", "revenue": 10331050.0}, {"channel": "Tiktok Shop", "revenue": 9359900.0}, {"channel": "Shopee ", "revenue": 9201100.0}, {"channel": "Tokopedia ", "revenue": 9141850.0}, {"channel": "shopee", "revenue": 9041100.0}, {"channel": "Tokopdia", "revenue": 8471350.0}, {"channel": "tiktok shop", "revenue": 8157250.0}, {"channel": "SHOPEE", "revenue": 8074950.0}, {"channel": "webstore", "revenue": 7834750.0}, {"channel": " Tokopedia", "revenue": 6844200.0}], "description_en": "Returns the correct 23 row(s) with the right values", "description_id": "Mengembalikan 23 baris yang benar dengan nilai yang tepat", "points": 70}, {"id": "tc2", "validation_type": "contains_columns", "expected_columns": ["channel", "revenue"], "description_en": "Returns the required columns: channel, revenue", "description_id": "Mengembalikan kolom yang diminta: channel, revenue", "points": 30}]'::jsonb,
    hints_en = '["Discount is a fraction — multiply by (1 - discount_pct)", "Wrap the SUM in ROUND() so the result has no decimals"]'::jsonb,
    hints_id = '["Diskon berupa pecahan — kalikan dengan (1 - discount_pct)", "Bungkus SUM dengan ROUND() agar hasilnya tanpa desimal"]'::jsonb,
    difficulty = 'medium',
    dataset_name = 'seduh'
FROM public.sessions s
WHERE e.session_id = s.id AND s.session_number = 'X04' AND e.order_num = 3;

