-- #4 — Q1 — Profit by Category, Not Revenue
UPDATE public.exercises e
SET type = 'sql',
    title_en = 'Q1 — Profit by Category, Not Revenue',
    title_id = 'Q1 — Profit per Kategori, Bukan Revenue',
    description_en = 'The category that sells most is not always the one that earns most. `unit_cost` lives in `products`, so you need a JOIN. Profit per line is `quantity * (unit_price * (1 - discount_pct) - unit_cost)`, completed orders only. Return exactly: `category`, `profit` (rounded), highest first. Inconsistent category names split two of the six categories in two — that is what Session 2 will fix.',
    description_id = 'Kategori yang paling laku belum tentu yang paling untung. `unit_cost` ada di `products`, jadi kamu butuh JOIN. Profit per baris = `quantity * (unit_price * (1 - discount_pct) - unit_cost)`, hanya order Completed. Kembalikan tepat: `category`, `profit` (dibulatkan), tertinggi dulu. Penamaan kategori yang tidak konsisten memecah dua dari enam kategori — itulah yang akan diperbaiki di Sesi 2.',
    starter_code = '-- Q1: profit per category (needs products.unit_cost)
-- Return: category, profit
',
    solution_code = 'SELECT p.category, ROUND(SUM(o.quantity * (o.unit_price * (1 - o.discount_pct) - p.unit_cost))) AS profit FROM orders o JOIN products p ON p.product_id = o.product_id WHERE o.order_status = ''Completed'' GROUP BY p.category ORDER BY profit DESC;',
    test_cases = '[{"id": "tc1", "validation_type": "exact_match", "expected_rows": [{"category": "Roasted Beans", "profit": 1700364150.0}, {"category": "Accessories", "profit": 317251600.0}, {"category": "Brewing Equipment", "profit": 243978650.0}, {"category": "Subscription", "profit": 231213900.0}, {"category": "Gift Set", "profit": 219041700.0}, {"category": "Ready to Drink", "profit": 207704650.0}, {"category": "Ready-to-Drink", "profit": 186977600.0}, {"category": "Roasted Beans ", "profit": 141378900.0}, {"category": "Gift set", "profit": 19233500.0}], "description_en": "Returns the correct 9 row(s) with the right values", "description_id": "Mengembalikan 9 baris yang benar dengan nilai yang tepat", "points": 70}, {"id": "tc2", "validation_type": "contains_columns", "expected_columns": ["category", "profit"], "description_en": "Returns the required columns: category, profit", "description_id": "Mengembalikan kolom yang diminta: category, profit", "points": 30}]'::jsonb,
    hints_en = '["JOIN products ON p.product_id = o.product_id", "Subtract unit_cost per unit, then multiply by quantity"]'::jsonb,
    hints_id = '["JOIN products ON p.product_id = o.product_id", "Kurangi unit_cost per unit, lalu kalikan dengan quantity"]'::jsonb,
    difficulty = 'medium',
    dataset_name = 'seduh'
FROM public.sessions s
WHERE e.session_id = s.id AND s.session_number = 'X04' AND e.order_num = 4;

