-- Return: category, profit
', 'SELECT p.category, ROUND(SUM(o.quantity * (o.unit_price * (1 - o.discount_pct) - p.unit_cost))) AS profit FROM orders o JOIN products p ON p.product_id = o.product_id WHERE o.order_status = ''Completed'' GROUP BY p.category ORDER BY profit DESC;',
  '[{"id": "tc1", "validation_type": "exact_match", "expected_rows": [{"category": "Roasted Beans", "profit": 1700364150.0}, {"category": "Accessories", "profit": 317251600.0}, {"category": "Brewing Equipment", "profit": 243978650.0}, {"category": "Subscription", "profit": 231213900.0}, {"category": "Gift Set", "profit": 219041700.0}, {"category": "Ready to Drink", "profit": 207704650.0}, {"category": "Ready-to-Drink", "profit": 186977600.0}, {"category": "Roasted Beans ", "profit": 141378900.0}, {"category": "Gift set", "profit": 19233500.0}], "description_en": "Returns the correct 9 row(s) with the right values", "description_id": "Mengembalikan 9 baris yang benar dengan nilai yang tepat", "points": 70}, {"id": "tc2", "validation_type": "contains_columns", "expected_columns": ["category", "profit"], "description_en": "Returns the required columns: category, profit", "description_id": "Mengembalikan kolom yang diminta: category, profit", "points": 30}]'::jsonb,
