-- #5 — Q3 — Monthly Revenue in 2025
UPDATE public.exercises e
SET type = 'sql',
    title_en = 'Q3 — Monthly Revenue in 2025',
    title_id = 'Q3 — Revenue Bulanan di 2025',
    description_en = 'Build the 2025 trend. `order_date` is text in `YYYY-MM-DD` form, so `substr(order_date, 1, 7)` gives you the month. Completed orders only. Return exactly: `month`, `revenue` (rounded), in date order. A few hundred rows still store the date as `dd/mm/yyyy` text, so this filter quietly skips them — check how many before you trust the trend.',
    description_id = 'Bangun tren 2025. `order_date` berupa teks `YYYY-MM-DD`, jadi `substr(order_date, 1, 7)` memberi bulannya. Hanya order Completed. Kembalikan tepat: `month`, `revenue` (dibulatkan), urut tanggal. Beberapa ratus baris masih menyimpan tanggal sebagai teks `dd/mm/yyyy`, jadi filter ini diam-diam melewatkannya — cek berapa banyak sebelum memercayai trennya.',
    starter_code = '-- Q3: monthly revenue for 2025 only
-- Return: month, revenue
',
    solution_code = 'SELECT substr(order_date, 1, 7) AS month, ROUND(SUM(quantity * unit_price * (1 - discount_pct))) AS revenue FROM orders WHERE order_status = ''Completed'' AND order_date >= ''2025-01-01'' AND order_date < ''2026-01-01'' GROUP BY month ORDER BY month;',
    test_cases = '[{"id": "tc1", "validation_type": "exact_match", "expected_rows": [{"month": "2025-01", "revenue": 248762250.0}, {"month": "2025-02", "revenue": 224568000.0}, {"month": "2025-03", "revenue": 340489700.0}, {"month": "2025-04", "revenue": 295243050.0}, {"month": "2025-05", "revenue": 268817500.0}, {"month": "2025-06", "revenue": 282653750.0}, {"month": "2025-07", "revenue": 289363850.0}, {"month": "2025-08", "revenue": 322461700.0}, {"month": "2025-09", "revenue": 326811900.0}, {"month": "2025-10", "revenue": 337617700.0}, {"month": "2025-11", "revenue": 413881800.0}, {"month": "2025-12", "revenue": 385034300.0}], "description_en": "Returns the correct 12 row(s) with the right values", "description_id": "Mengembalikan 12 baris yang benar dengan nilai yang tepat", "points": 70}, {"id": "tc2", "validation_type": "contains_columns", "expected_columns": ["month", "revenue"], "description_en": "Returns the required columns: month, revenue", "description_id": "Mengembalikan kolom yang diminta: month, revenue", "points": 30}]'::jsonb,
    hints_en = '["substr(order_date, 1, 7) turns 2025-03-14 into 2025-03", "Filter the year in WHERE, then GROUP BY the month expression"]'::jsonb,
    hints_id = '["substr(order_date, 1, 7) mengubah 2025-03-14 menjadi 2025-03", "Filter tahunnya di WHERE, lalu GROUP BY ekspresi bulan tersebut"]'::jsonb,
    difficulty = 'medium',
    dataset_name = 'seduh'
FROM public.sessions s
WHERE e.session_id = s.id AND s.session_number = 'X04' AND e.order_num = 5;

