-- #6 — Cities Worth Their Own Campaign
UPDATE public.exercises e
SET type = 'sql',
    title_en = 'Cities Worth Their Own Campaign',
    title_id = 'Kota yang Layak Dapat Kampanye Sendiri',
    description_en = 'Marketing wants to launch city-level campaigns, but only where the volume justifies it — cities with more than 900 completed orders. Which cities clear that bar? Return exactly: `city`, `orders`, busiest first.',
    description_id = 'Tim marketing ingin meluncurkan kampanye di level kota, tapi hanya di kota dengan volume yang cukup besar — lebih dari 900 order Completed. Kota mana saja yang lolos? Kembalikan tepat: `city`, `orders`, terbanyak dulu.',
    starter_code = '-- Cities with more than 900 completed orders
-- Return: city, orders
',
    solution_code = 'SELECT city, COUNT(*) AS orders FROM orders WHERE order_status = ''Completed'' GROUP BY city HAVING COUNT(*) > 900 ORDER BY orders DESC;',
    test_cases = '[{"id": "tc1", "validation_type": "exact_match", "expected_rows": [{"city": "Balikpapan", "orders": 4403}, {"city": "Bandung", "orders": 2589}, {"city": "Surabaya", "orders": 2261}, {"city": "Semarang", "orders": 1413}, {"city": "Bekasi", "orders": 1396}, {"city": "Medan", "orders": 1202}, {"city": "Tangerang", "orders": 1170}, {"city": "Depok", "orders": 1113}, {"city": "Malang", "orders": 1105}, {"city": "Yogyakarta", "orders": 936}, {"city": "Bogor", "orders": 914}], "description_en": "Returns the correct 11 row(s) with the right values", "description_id": "Mengembalikan 11 baris yang benar dengan nilai yang tepat", "points": 70}, {"id": "tc2", "validation_type": "contains_columns", "expected_columns": ["city", "orders"], "description_en": "Returns the required columns: city, orders", "description_id": "Mengembalikan kolom yang diminta: city, orders", "points": 30}]'::jsonb,
    hints_en = '["WHERE runs before grouping, HAVING runs after", "You still need the completed-orders filter in WHERE"]'::jsonb,
    hints_id = '["WHERE berjalan sebelum pengelompokan, HAVING sesudahnya", "Filter order Completed tetap diperlukan di WHERE"]'::jsonb,
    difficulty = 'hard',
    dataset_name = 'seduh'
FROM public.sessions s
WHERE e.session_id = s.id AND s.session_number = 'X04' AND e.order_num = 6;

