-- #7 — Q6 — Which Acquisition Channel Brings the Best Customers?
UPDATE public.exercises e
SET type = 'sql',
    title_en = 'Q6 — Which Acquisition Channel Brings the Best Customers?',
    title_id = 'Q6 — Channel Akuisisi Mana yang Membawa Customer Terbaik?',
    description_en = 'Marketing spends across six acquisition channels, but which ones actually bring customers who buy, not just click? For each channel, compare how many distinct customers converted and how much revenue they generated (completed orders only). Return exactly: `acquisition_channel`, `customers` (distinct buyers), `revenue` (rounded), highest revenue first.',
    description_id = 'Tim marketing beriklan lewat enam acquisition channel, tapi channel mana yang benar-benar mendatangkan pembeli, bukan sekadar klik? Untuk tiap channel, bandingkan berapa banyak pelanggan unik yang benar-benar membeli dan berapa revenue yang mereka hasilkan (hanya order Completed). Kembalikan tepat: `acquisition_channel`, `customers` (pembeli unik), `revenue` (dibulatkan), revenue tertinggi dulu.',
    starter_code = '-- Q6: value of each acquisition channel
-- Return: acquisition_channel, customers, revenue
',
    solution_code = 'SELECT c.acquisition_channel, COUNT(DISTINCT o.customer_id) AS customers, ROUND(SUM(o.quantity * o.unit_price * (1 - o.discount_pct))) AS revenue FROM orders o JOIN customers c ON c.customer_id = o.customer_id WHERE o.order_status = ''Completed'' GROUP BY c.acquisition_channel ORDER BY revenue DESC;',
    test_cases = '[{"id": "tc1", "validation_type": "exact_match", "expected_rows": [{"acquisition_channel": "Instagram Ads", "customers": 3271, "revenue": 1517831600.0}, {"acquisition_channel": "Google Search", "customers": 2220, "revenue": 1379529900.0}, {"acquisition_channel": "Referral", "customers": 1854, "revenue": 1341542300.0}, {"acquisition_channel": "Organic Social", "customers": 2395, "revenue": 1310689900.0}, {"acquisition_channel": "TikTok Ads", "customers": 1987, "revenue": 650212300.0}, {"acquisition_channel": "Marketplace", "customers": 1653, "revenue": 582384650.0}], "description_en": "Returns the correct 6 row(s) with the right values", "description_id": "Mengembalikan 6 baris yang benar dengan nilai yang tepat", "points": 70}, {"id": "tc2", "validation_type": "contains_columns", "expected_columns": ["acquisition_channel", "customers", "revenue"], "description_en": "Returns the required columns: acquisition_channel, customers, revenue", "description_id": "Mengembalikan kolom yang diminta: acquisition_channel, customers, revenue", "points": 30}]'::jsonb,
    hints_en = '["COUNT(DISTINCT ...) so a repeat buyer is not counted twice", "Spend lives in marketing_spend, but its channel names differ — that is the next step"]'::jsonb,
    hints_id = '["COUNT(DISTINCT ...) agar repeat buyer tidak terhitung dua kali", "Spend ada di marketing_spend, tapi nama channel-nya berbeda — itu langkah berikutnya"]'::jsonb,
    difficulty = 'hard',
    dataset_name = 'seduh'
FROM public.sessions s
WHERE e.session_id = s.id AND s.session_number = 'X04' AND e.order_num = 7;

