-- #8 — Q7 — Does Discounting Actually Pay?
UPDATE public.exercises e
SET type = 'sql',
    title_en = 'Q7 — Does Discounting Actually Pay?',
    title_id = 'Q7 — Apakah Diskon Benar-benar Menguntungkan?',
    description_en = 'Sales keeps pushing deeper discounts to move volume, but does it actually pay off? For each discount tier, compare average order quantity against margin (`profit / revenue * 100`) on completed orders. Return exactly: `discount_pct`, `avg_quantity` (rounded to 2 decimals), `margin_pct` (rounded to 1 decimal), by discount ascending. Read the answer off your own result.',
    description_id = 'Tim sales terus mendorong diskon yang lebih dalam demi mengejar volume, tapi apakah itu benar-benar menguntungkan? Untuk tiap tingkat diskon, bandingkan rata-rata quantity per order dengan margin (`profit / revenue * 100`) pada order Completed. Kembalikan tepat: `discount_pct`, `avg_quantity` (2 desimal), `margin_pct` (1 desimal), urut diskon menaik. Baca jawabannya dari hasilmu sendiri.',
    starter_code = '-- Q7: discount depth vs volume vs margin
-- Return: discount_pct, avg_quantity, margin_pct
',
    solution_code = 'SELECT o.discount_pct, ROUND(AVG(o.quantity), 2) AS avg_quantity, ROUND(SUM(o.quantity * (o.unit_price * (1 - o.discount_pct) - p.unit_cost)) * 100.0 / SUM(o.quantity * o.unit_price * (1 - o.discount_pct)), 1) AS margin_pct FROM orders o JOIN products p ON p.product_id = o.product_id WHERE o.order_status = ''Completed'' GROUP BY o.discount_pct ORDER BY o.discount_pct;',
    test_cases = '[{"id": "tc1", "validation_type": "exact_match", "expected_rows": [{"discount_pct": 0.0, "avg_quantity": 2.17, "margin_pct": 51.3}, {"discount_pct": 0.05, "avg_quantity": 2.52, "margin_pct": 49.0}, {"discount_pct": 0.1, "avg_quantity": 2.82, "margin_pct": 46.3}, {"discount_pct": 0.15, "avg_quantity": 3.03, "margin_pct": 43.4}, {"discount_pct": 0.2, "avg_quantity": 3.28, "margin_pct": 39.4}, {"discount_pct": 0.25, "avg_quantity": 3.55, "margin_pct": 35.4}], "description_en": "Returns the correct 6 row(s) with the right values", "description_id": "Mengembalikan 6 baris yang benar dengan nilai yang tepat", "points": 70}, {"id": "tc2", "validation_type": "contains_columns", "expected_columns": ["discount_pct", "avg_quantity", "margin_pct"], "description_en": "Returns the required columns: discount_pct, avg_quantity, margin_pct", "description_id": "Mengembalikan kolom yang diminta: discount_pct, avg_quantity, margin_pct", "points": 30}]'::jsonb,
    hints_en = '["Compute profit and revenue in the same query, then divide", "Multiply by 100.0 — integer division would flatten the result to 0"]'::jsonb,
    hints_id = '["Hitung profit dan revenue dalam satu query, lalu bagi", "Kalikan dengan 100.0 — pembagian integer akan membuat hasilnya 0"]'::jsonb,
    difficulty = 'hard',
    dataset_name = 'seduh'
FROM public.sessions s
WHERE e.session_id = s.id AND s.session_number = 'X04' AND e.order_num = 8;

